import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.k9nOhppk.js";const f=JSON.parse('{"title":"Language reference","description":"","frontmatter":{"title":"Language reference"},"headers":[],"relativePath":"reference/language/index.md","filePath":"reference/language/index.md","lastUpdated":1791864160000}'),s={name:"reference/language/index.md"};function o(i,e,d,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="language-reference" tabindex="-1">Language reference <a class="header-anchor" href="#language-reference" aria-label="Permalink to &quot;Language reference&quot;">​</a></h1><p>Eyelang 2 is a general-purpose, statically typed, compiled language for <strong>software that keeps state and waits</strong>: services, automations, schedulers and agents that run for days, wait for people, hold data, call other services that fail, and spend most of their time waiting. It lets you write such a program as plainly as a script, and its compiler catches the mistakes such programs usually ship with. Typically that means data spread across many entities (users, devices, game worlds, apps) and jobs that run briefly and then wait for minutes, hours or days. It is not a configuration DSL: every feature below is an ordinary language construct that also works outside that domain. <a href="/design/goals">Section 1</a> lists what the language promises and the principles it is designed by.</p><h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h2><p>Words this document uses in one sense, and names that mean different things in different places.</p><table tabindex="0"><thead><tr><th>Word</th><th>Meaning</th></tr></thead><tbody><tr><td>run</td><td>One execution of a job, from its start to its outcome. Each start makes one, unless its key started one already; <code>Run(a)</code> is the value that names it (<a href="/reference/language/jobs-and-waiting">section 15</a>).</td></tr><tr><td>step</td><td>A <code>!</code> call in a job. It runs once, and its result is recorded in the run, so a resumed run gets the recorded result instead of calling again (<a href="/reference/language/effects-and-signatures">section 12</a>).</td></tr><tr><td>checkpoint</td><td>A run&#39;s saved place: its live variables, the statement it is at, and where each loop around it is. The interpreter takes one at a statement of the job&#39;s body once steps have been taken since the last; a run that wakes restores the latest and replays only the steps since (<a href="/reference/language/jobs-and-waiting">section 15</a>). <code>zeropod.checkpoint!</code> in the tour is an operation of a service, not this.</td></tr><tr><td>transaction</td><td>What runs all or nothing: an entity method&#39;s call tree, a served operation, or a job&#39;s step that calls an entity. Jobs it starts and events it publishes happen only if it commits (<a href="/reference/language/entities">section 14</a>).</td></tr><tr><td>key</td><td>An idempotency key, a <code>Key</code>: what tells one command, job start or event from a repeat of it, so the same key never does the work twice (<code>key:</code> on a call, <code>@key</code> on an operation or event). A map&#39;s keys are ordinary values.</td></tr><tr><td>version</td><td>A snapshot&#39;s <code>version</code> is a <code>Version</code> that counts the transactions that changed the entity, and is what a <code>@fresh</code> command&#39;s <code>basedOn</code> takes (sections 14 and 17). <code>@version(N)</code> numbers the shape of an entity&#39;s stored state, for migrations. A state field can&#39;t be named <code>version</code>.</td></tr><tr><td>handler</td><td>What <code>with</code> applies to the rest of a test&#39;s block: <code>clock(…)</code>, of the built-in type <code>Handler</code>, and <code>fakes(…)</code>, of the built-in type <code>Fakes</code>, which also lists the calls it answered (<a href="/reference/language/time-secrets-tests">section 20</a>). A program may declare its own <code>Handler</code>, as <a href="/reference/language/effects-and-signatures">section 12</a>&#39;s example does; in its module the name is the program&#39;s.</td></tr><tr><td>outcome</td><td>A run&#39;s <code>Outcome</code>, <code>Completed(value)</code> or <code>Failed(fault)</code> (<a href="/reference/language/jobs-and-waiting">section 15</a>); a command&#39;s outcome is the variant its result is (<a href="/reference/language/contracts-talking-to-other-services">section 17</a>).</td></tr><tr><td>fault</td><td>What ends a run that code can&#39;t catch, such as <code>DeadlinePassed</code> or <code>Unreachable</code> (<a href="/reference/language/jobs-and-waiting">section 15</a>). An <code>Err</code> is a value, not a fault.</td></tr><tr><td>method</td><td>What <code>x.f(a)</code> calls: a method of <code>x</code>&#39;s type, from its <code>impl</code>, an entity&#39;s or a trait&#39;s; else a field of <code>x</code> that holds a function; else a function in scope whose first parameter takes <code>x</code>, as <code>f(x, a)</code> (<a href="/reference/language/methods-and-generics">section 8</a>).</td></tr><tr><td>callback</td><td>A function given to a parameter whose function type has no <code>uses</code>, as <code>filter</code>&#39;s. It can&#39;t be kept, so it runs before the call returns: its effects count where it is given (<a href="/reference/language/effects-and-signatures">section 12</a>), and a lambda given as one may read a <code>var</code> (<a href="/reference/language/mutation">section 7</a>).</td></tr><tr><td><code>end</code></td><td>In an entity&#39;s own method, <code>end(ok)</code> ends the entity (<a href="/reference/language/entities">section 14</a>). Elsewhere <code>s.end()</code> is a string&#39;s end position, and <code>r.end</code> a range&#39;s end.</td></tr><tr><td><code>start</code></td><td><code>j.start(…)</code> starts a run of job <code>j</code>, and <code>claude.start!(…)</code> an agent&#39;s session. <code>s.start()</code> is a string&#39;s first position, and <code>r.start</code> a range&#39;s start.</td></tr><tr><td><code>first</code></td><td><code>first(xs)</code> is a collection&#39;s first element, an <code>Option</code>. Waiting for whichever of several runs finishes first is <code>firstDone!</code>, and for all of them <code>allDone!</code>, named apart from <code>first</code> and <code>all</code> (<a href="/reference/language/jobs-and-waiting">section 15</a>).</td></tr><tr><td><code>join</code></td><td><code>xs |&gt; join(&quot;, &quot;)</code> joins strings; <code>run.join!()</code> waits for a run&#39;s outcome, in a job. A test or <code>main</code> reads the outcome without waiting, with <code>run.outcome()</code>, and <code>run.join()</code> on a run is an error that says so.</td></tr></tbody></table><p>Each page is one section of the language&#39;s specification, <a href="https://github.com/ruxxzebre/eyelang/blob/dev/SPECS.md" target="_blank" rel="noreferrer">SPECS.md</a>, which is where the rules are written and changed.</p><ul><li><a href="/reference/language/a-tour">A tour</a></li><li><a href="/reference/language/lexical-structure">Lexical structure</a></li><li><a href="/reference/language/values-and-types">Values and types</a></li><li><a href="/reference/language/bindings-functions-and-pipes">Bindings, functions and pipes</a></li><li><a href="/reference/language/mutation">Mutation</a></li><li><a href="/reference/language/methods-and-generics">Methods and generics</a></li><li><a href="/reference/language/pattern-matching">Pattern matching</a></li><li><a href="/reference/language/errors-result-only">Errors: Result only</a></li><li><a href="/reference/language/traits">Traits</a></li><li><a href="/reference/language/effects-and-signatures">Effects and signatures</a></li><li><a href="/reference/language/programs-and-concurrency">Programs and concurrency</a></li><li><a href="/reference/language/entities">Entities</a></li><li><a href="/reference/language/jobs-and-waiting">Jobs and waiting</a></li><li><a href="/reference/language/views-and-triggers">Views and triggers</a></li><li><a href="/reference/language/contracts-talking-to-other-services">Contracts: talking to other services</a></li><li><a href="/reference/language/calling-c-and-go">Calling C and Go</a></li><li><a href="/reference/language/ai-models-and-agents">AI models and agents</a></li><li><a href="/reference/language/time-secrets-tests">Time, secrets, tests</a></li><li><a href="/reference/language/grammar-sketch">Grammar sketch</a></li></ul>',7)])])}const u=a(s,[["render",o]]);export{f as __pageData,u as default};
